    object MergeAssemblies(string workspace,Dictionary<string,object> values){string ours=RepositoryGit.Resolve(workspace,"HEAD"),reference=ValueText(values,"reference");string theirs=RepositoryGit.Resolve(workspace,String.IsNullOrEmpty(reference)?"MERGE_HEAD":reference);return new {ours=ours,theirs=theirs,oursAssemblies=TreeCad(workspace,ours).Where(file=>file.EndsWith(".sldasm",StringComparison.OrdinalIgnoreCase)).ToArray(),theirsAssemblies=TreeCad(workspace,theirs).Where(file=>file.EndsWith(".sldasm",StringComparison.OrdinalIgnoreCase)).ToArray()};}
