    static string[] Items(object value){return value is IEnumerable?((IEnumerable)value).Cast<object>().Select(Convert.ToString).ToArray():new string[0];}
    string[] DirectReferences(string file){string[] values=Items(app.GetDocumentDependencies2(file,false,false,false));var result=new List<string>();for(int i=1;i<values.Length;i+=2)if(!String.IsNullOrWhiteSpace(values[i]))result.Add(values[i]);return result.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
