    static CadMergeFile FindSource(CadMergeSession session,string side,string reference,string snapshot){
      var files=session.Files.Where(file=>file.Side==side).ToArray();string normalized=reference.Replace('\\','/');var matches=files.Where(file=>String.Equals(normalized,(session.Workspace+"/"+file.Relative).Replace('\\','/'),StringComparison.OrdinalIgnoreCase)||String.Equals(normalized,(snapshot+"/"+file.Relative).Replace('\\','/'),StringComparison.OrdinalIgnoreCase)).ToArray();if(matches.Length==1)return matches[0];
