      throw new InvalidOperationException("无法唯一匹配分支中的关联图纸："+reference+"。请把外部/虚拟零件保存到仓库，并消除不明确的同名引用后重新导入。");
    }
    async Task PrepareMergeSide(string workspace,CadMergeSession session,string side,string oid){
      string snapshot=Path.Combine(session.Root,"snapshot-"+side),copy=Path.Combine(session.Root,side);Directory.CreateDirectory(copy);bool registered=false;
