        Progress("正在取出"+(side=="ours"?"当前":"合入")+"分支完整图纸 · "+oid.Substring(0,7));await Git.ProcessAsync("git.exe",workspace,new string[]{"worktree","add","--detach",snapshot,oid},true);registered=true;RequireRunning();
        var files=await Task.Run(()=>TreeCad(snapshot,oid));var lfs=new List<string>{"lfs","checkout"};foreach(string extension in files.Select(Path.GetExtension).Distinct(StringComparer.OrdinalIgnoreCase)){lfs.Add("*"+extension.ToLowerInvariant());lfs.Add("*"+extension.ToUpperInvariant());}if(lfs.Count>2)await Git.Async(snapshot,lfs.ToArray());
        bool missing=await Task.Run(()=>files.Any(file=>IsPointer(SafePath(snapshot,file))));if(missing){if(String.IsNullOrEmpty(Git.Try(workspace,"remote","get-url","origin")))throw new InvalidOperationException("本机缺少历史 LFS 图纸，且未配置 origin。");await Git.Async(snapshot,"lfs","pull","--include="+String.Join(",",lfs.Skip(2)),"--exclude=");}RequireRunning();
        int index=0;foreach(string relative in files){string original=SafePath(snapshot,relative);if(IsPointer(original))throw new InvalidOperationException("未取到实际 LFS 图纸："+relative);string name=(side=="ours"?"A_":"B_")+session.Id.Substring(0,6)+"_"+(index++).ToString("D4")+"_"+Path.GetFileName(relative);string output=Path.Combine(copy,name);File.Copy(original,output,false);File.SetAttributes(output,FileAttributes.Normal);session.Files.Add(new CadMergeFile{Path=output,Relative=relative,Side=side});}
        // Rewrite saved references while every document is closed. Unique document names keep
        // SolidWorks from substituting an already loaded same-name part from the other branch.
        var pending=new Queue<CadMergeFile>();var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase);pending.Enqueue(session.Files.Single(file=>file.Side==side&&file.Relative==(side=="ours"?session.OursAssembly:session.TheirsAssembly)));
        while(pending.Count>0){var file=pending.Dequeue();if(!visited.Add(file.Path))continue;
          foreach(string reference in DirectReferences(file.Path)){var dependency=FindSource(session,side,reference,snapshot);pending.Enqueue(dependency);if(!app.ReplaceReferencedDocument(file.Path,reference,dependency.Path))throw new InvalidOperationException("无法重连分支装配引用："+file.Relative+" → "+dependency.Relative);}
          foreach(string reference in DirectReferences(file.Path))if(!session.Files.Any(dependency=>dependency.Side==side&&Same(reference,dependency.Path)))throw new InvalidOperationException("分支装配仍引用了副本外的文件："+reference);
          await Task.Yield();RequireRunning();
        }
        session.Files.RemoveAll(file=>file.Side==side&&!visited.Contains(file.Path));
      }finally{if(registered)Git.Run(workspace,"worktree","remove","--force",snapshot);}
    }
